"Quitter":"退出",
"Partager tout ton carnet ?\n\nLa personne recevra un code compagnon : elle verra TOUS tes voyages et pourra les compléter, sans tes droits d’administrateur (pas d’effacement, pas de gestion des accès). Tu pourras lui retirer l’accès. Pour ne partager qu’un voyage, utilise plutôt « Inviter » sur ce voyage.":"共享你的整本手账？\n\n对方将收到一个同伴码：可以看到你的所有旅行并补充，但没有你的管理员权限（不能删除，不能管理权限）。你可以收回其权限。如只想共享一次旅行，请在该旅行中使用“邀请”。",
"Ils reçoivent un code compagnon et voient tous tes voyages, sans tes droits d’administrateur. Pour ta famille ou ton couple.":"他们会收到同伴码，看到你的所有旅行，但没有你的管理员权限。适合家人或伴侣。",
