"Sur iPhone : ajoute Vezoria à l’écran d’accueil (Safari → Partager → « Sur l’écran d’accueil ») et ouvre-la de là. Garde aussi une 💾 sauvegarde complète de temps en temps.":"iPhone 上：把 Vezoria 添加到主屏幕（Safari → 分享 →「添加到主屏幕」），并从那里打开。也要时不时做一次 💾 完整备份。",
"Installe Vezoria (Google Play ou « Installer l’appli ») et ouvre-la souvent : Android protège alors son stockage. Garde aussi une 💾 sauvegarde complète de temps en temps.":"安装 Vezoria（Google Play 或「安装应用」）并经常打开：这样 Android 会保护它的存储。也要时不时做一次 💾 完整备份。",
"🧹 Libérer de la place":"🧹 腾出空间",
"Pour les voyages terminés ({0}), les grandes photos déjà envoyées sur le serveur sont retirées de ce téléphone. Les vignettes restent : la grille et le film s’affichent toujours, et la grande photo revient du serveur, en version allégée, quand tu l’ouvres (il faut du réseau). Les photos pas encore envoyées ne sont jamais touchées.":"对于已结束的旅行（{0}），已上传到服务器的大图会从这部手机上移除。缩略图会保留：网格和影片照常显示，打开大图时会从服务器取回轻量版本（需要网络）。尚未上传的照片绝不会被动。",
"Retirer de ce téléphone les grandes photos des voyages terminés déjà sur le serveur ? Les vignettes restent, et chaque grande photo revient quand tu l’ouvres.":"从这部手机上移除已结束旅行中、服务器上已有的大图？缩略图会保留，每张大图在你打开时会回来。",
"🧹 {0} / {1}…":"🧹 {0} / {1}…",
"✅ {0} grande(s) photo(s) retirée(s) de ce téléphone · {1} Mo libérés.":"✅ 已从这部手机移除 {0} 张大图 · 释放 {1} MB。",
"Rien à libérer pour le moment (photos pas encore envoyées, ou déjà libérées).":"目前没有可腾出的空间（照片尚未上传，或已经移除）。",
