"Crée le code de ce voyage et invite tes compagnons : ils ne voient que ce voyage, le reste reste privé.":"创建这次旅行的代码并邀请旅伴：他们只能看到这次旅行，其他内容保持私密。",
"🔗 Créer le code et inviter":"🔗 创建代码并邀请",
"🤝 Rejoindre un voyage avec un code":"🤝 用代码加入旅行",
"Rien n’est en ligne pour l’instant : tes voyages restent sur ce téléphone.":"目前没有任何内容在线：你的旅行只保存在这部手机上。",
"Créer ton code principal ?\n\nTous tes voyages seront sauvegardés sur le serveur, chiffrés sur ce téléphone : personne d’autre ne peut les lire. Garde bien ce code : c’est lui qui ouvre ton carnet sur un autre appareil.":"创建你的主代码？\n\n你的所有旅行都会备份到服务器，并在这部手机上加密：其他人无法读取。请妥善保管这个代码：在其他设备上打开你的旅行手账全靠它。",
"Code trop court (au moins 8 caractères).":"代码太短（至少 8 个字符）。",
