"🌍 14 langues (français, anglais, espagnol, allemand, italien, portugais, néerlandais, russe, turc, arabe, hindi, chinois, japonais, coréen) et la devise de ton choix.":"🌍 14 种语言（法语、英语、西班牙语、德语、意大利语、葡萄牙语、荷兰语、俄语、土耳其语、阿拉伯语、印地语、中文、日语、韩语），以及你选择的货币。",
"👀 Des abonnés, comme Polarsteps : tes proches suivent le voyage (photos en vignettes et récits), mettent des ❤️ et des commentaires.":"👀 关注者功能，就像 Polarsteps：亲友可以关注旅行（照片缩略图和游记），点 ❤️ 和评论。",
"👥 Une fenêtre « Abonnés & partages », avec une pastille dès qu’il y a du nouveau.":"👥 「关注者与分享」窗口，有新动态时会显示小红点。",
"🛰️ Ta route sur la carte pour tes abonnés, seulement si tu l’actives.":"🛰️ 只有你开启后，关注者才能在地图上看到你的路线。",
"🚩 Signaler, bloquer ou masquer quelqu’un, et créer un nouveau lien abonné.":"🚩 举报、屏蔽或隐藏某人，以及创建新的关注链接。",
"🎬 Le film du voyage en musique (11 musiques), avec la carte zoomée région par région.":"🎬 配乐旅行影片（11 首音乐），地图逐个地区放大展示。",
"📷 « Ranger mes photos » : les photos se placent toutes seules au bon jour et au bon endroit.":"📷 「整理我的照片」：照片会自动归到正确的日期和地点。",
"🗺️ Le programme et le voyage en cours sur la carte.":"🗺️ 在地图上查看行程计划和正在进行的旅行。",
"💱 La conversion des devises dans les dépenses et les tickets.":"💱 开销和票据中的货币换算。",
"🎨 Des couleurs pour chaque moment : préparation, voyage en cours, souvenirs.":"🎨 每个阶段都有专属颜色：准备、旅行中、回忆。",
"☁️ Une synchro plus économe, voyage par voyage, avec l’état de l’envoi en un coup d’œil.":"☁️ 更省流量的同步，逐个旅行进行，上传状态一目了然。",
"🔐 Un chiffrement renforcé dans la version finale.":"🔐 最终版本将采用更强的加密。",
"🎓 Un nouveau tuto vidéo de 3 minutes.":"🎓 全新 3 分钟视频教程。",
"🛫 Escale (recherche de vols, Radar des prix) : pour respecter les règles de Google Play, Escale ne sera pas dans la version finale de Vezoria. Le module fait appel à trop de services extérieurs pour être publié.":"🛫 Escale（机票搜索、价格雷达）：为遵守 Google Play 的规定，Escale 不会出现在 Vezoria 的最终版本中。该模块调用了太多外部服务，无法发布。",
"🔕 Aucune notification : Vezoria ne t’envoie rien.":"🔕 没有任何通知：Vezoria 从不打扰你。",
"📥 L’import depuis Polarsteps n’est pas encore dans Vezoria.":"📥 Vezoria 暂时还不支持从 Polarsteps 导入。",
"Cette version test garde le stockage du carnet : même serveur, mêmes codes. Tes compagnons restés sur le carnet voient ce que tu fais dans Vezoria, et inversement.":"此测试版沿用手账的存储：同一服务器、同一代码。仍在使用手账的旅伴能看到你在 Vezoria 中的操作，反之亦然。",
"Avant la première ouverture de Vezoria, une copie de sauvegarde de ton carnet est gardée sur ce téléphone.":"首次打开 Vezoria 之前，会在这部手机上保留一份手账的备份。",
"📱 Vezoria sera sur Google Play (Android) et en appli web sur iPhone.":"📱 Vezoria 将上架 Google Play（安卓），并在 iPhone 上以网页应用形式提供。",
