"Supprimer ce commentaire ?":"删除这条评论？",
"Masquer les commentaires et ❤️ de cette personne sur ce téléphone ?":"在这部手机上隐藏此人的评论和 ❤️？",
"Bloquer {0} ?\n\nSes commentaires et ❤️ sont masqués pour tous tes abonnés et elle est retirée de la liste.\nPour l’empêcher aussi de voir tes souvenirs, touche ensuite « 🔁 Nouveau lien abonné » et renvoie le lien seulement aux personnes de ton choix.":"屏蔽 {0}？\n\n对方的评论和 ❤️ 将对你的所有关注者隐藏，并从列表中移除。\n若还要阻止对方查看你的回忆，请再点击「🔁 新的关注链接」，并只把链接发给你选择的人。",
"Créer un nouveau lien abonné ?\n\nL’ancien lien ne marchera plus : plus personne ne voit tes souvenirs tant que tu n’as pas renvoyé le nouveau lien. Les ❤️ et commentaires passés sont effacés.":"创建新的关注链接？\n\n旧链接将失效：在你重新发送新链接之前，没有人能看到你的回忆。之前的 ❤️ 和评论会被删除。",
"Pourquoi signales-tu ce contenu ? (contenu illicite, harcèlement, nudité, violence, autre…)":"你为什么要举报此内容？（违法内容、骚扰、裸露、暴力、其他…）",
