"Pour partager un seul voyage, inutile : dans le voyage, touche Partager. Seul ce voyage est alors stocké sur le serveur, tes autres voyages restent sur ton téléphone.":"如果只想分享一次旅行，不需要这个：在旅行中点击「分享」即可。届时只有这次旅行会存到服务器上，其他旅行仍留在你的手机里。",
