"Créer un nouveau code pour « {0} » ?\n\nLe voyage, ses fiches et ses photos repartent sur le serveur sous ce nouveau code. Les autres téléphones doivent ensuite le rejoindre avec le nouveau code (Mes voyages → Rejoindre un voyage partagé).":"为「{0}」创建新代码？\n\n旅行、条目和照片将以新代码重新上传到服务器。其他手机随后需要用新代码加入（我的旅行 → 加入共享旅行）。",
"⚠️ Le voyage n’a pas pu être envoyé sous le nouveau code : {0}\nRéessaie avec « Tout renvoyer » quand la connexion est bonne.":"⚠️ 无法以新代码上传旅行：{0}\n网络良好时，请用「全部重新上传」重试。",
