"Carnet perdu ?":"手账丢失了？",
"Tes voyages ont disparu de ce téléphone et tu n’as plus le code du carnet ? Si les notifications étaient activées, on peut les retrouver sur le serveur.":"旅行从这部手机上消失了，而且你也没有手账的代码了？如果之前开启了通知，可以在服务器上找回。",
"Récupérer un carnet perdu":"找回丢失的手账",
"Pour un carnet qui était dans le cloud, quand son code est perdu. Ce téléphone a gardé {0} clé(s) de chiffrement de carnets (celles des notifications).":"适用于曾在云端、但代码已丢失的手账。这部手机保留了 {0} 把手账加密密钥（通知用的）。",
"Clé d’administration du serveur (ADMIN_KEY)":"服务器管理密钥（ADMIN_KEY）",
"🛟 Chercher mes voyages":"🛟 查找我的旅行",
"Aucune clé sur ce téléphone : la récupération sans code n’est pas possible ici. Demande à un compagnon le code d’un voyage partagé (👥 Partager → 🔗 Rejoindre avec un code).":"这部手机上没有密钥：这里无法在没有代码的情况下找回。请向旅伴索要共享旅行的代码（👥 分享 → 🔗 用代码加入）。",
"Colle la clé d’administration.":"请粘贴管理密钥。",
"Lecture des clés de ce téléphone…":"正在读取这部手机的密钥…",
"Liste des carnets du serveur…":"正在列出服务器上的手账…",
"Aucun carnet du serveur ne s’ouvre avec les clés de ce téléphone.":"服务器上没有手账能用这部手机的密钥打开。",
"Carnet {0}/{1} : {2} fiches retrouvées…":"手账 {0}/{1}：已找到 {2} 条记录…",
"{0} fiches remises ({1} trouvées) · photos sur ce téléphone : {2}/{3}.":"已恢复 {0} 条记录（找到 {1} 条）· 这部手机上的照片：{2}/{3}。",
"Tes voyages sont revenus. Choisis ton ancien profil, puis crée un nouveau code principal (☁️ Cloud) et NOTE-LE : tout repartira sur le serveur.":"你的旅行回来了。选择你原来的个人资料，然后创建新的主代码（☁️ 云端）并记下来：所有内容会重新上传到服务器。",
"Ton carnet n’est pas dans le cloud : rien à séparer.":"你的手账不在云端：没有需要分开的内容。",
"Séparer mes voyages privés":"分开我的私人旅行",
"Séparer":"分开",
"Ton carnet principal (code {0}) est aussi chez les personnes qui ont ce code : elles voient tous ces voyages. Coche ceux à garder partagés avec elles. Les autres deviendront privés : ils partent dans un nouveau carnet rien qu’à toi, avec un nouveau code, et disparaissent chez les autres.":"你的主手账（代码 {0}）也在拥有此代码的人那里：他们能看到所有这些旅行。勾选要继续与他们共享的旅行。其余的将变为私人：转入只属于你的新手账（新代码），并从其他人那里消失。",
"{0} voyage(s) restent partagés, {1} voyage(s) deviennent privés ({2} fiches). Un nouveau code principal va être créé : il faudra le noter. Continuer ?":"{0} 个旅行继续共享，{1} 个旅行变为私人（{2} 条记录）。将创建新的主代码：需要记下来。继续？",
"Photos ramenées sur ce téléphone : {0}/{1}":"已取回到这部手机的照片：{0}/{1}",
"{0} photo(s) n’ont pas pu être ramenées (réseau ?). Continuer quand même ?":"有 {0} 张照片无法取回（网络问题？）。仍然继续？",
"Retrait du carnet partagé : {0}/{1}":"正在从共享手账中移除：{0}/{1}",
"Séparé. Note bien ton nouveau code principal.":"已分开。请务必记下新的主代码。",
"Carnet partagé par erreur ?":"手账被误共享了？",
"Quelqu’un a le code de ton carnet principal et voit tous tes voyages ? Garde partagés ceux que tu choisis, les autres redeviennent privés.":"有人拥有你主手账的代码并能看到你所有的旅行？保留你选择的共享旅行，其余的重新变为私人。",
"Réparer les liens des voyages":"修复旅行链接",
"Pour des voyages partagés dont les photos ou les mises à jour n’arrivent plus. L’appli retrouve le bon code de chaque voyage. Rien n’est effacé.":"适用于照片或更新不再到达的共享旅行。应用会找回每个旅行的正确代码。不会删除任何内容。",
"Réparer":"修复",
"Lecture des codes : {0}/{1}":"正在读取代码：{0}/{1}",
"Voyage {0}/{1} : {2}":"旅行 {0}/{1}：{2}",
"{0} voyage(s) rattaché(s) à leur bon code. Les photos reviennent au fur et à mesure.":"已将 {0} 个旅行关联到正确代码。照片会陆续回来。",
"Tous les voyages sont déjà sur leur bon code.":"所有旅行都已在正确的代码上。",
"Photos ou voyages partagés qui n’arrivent plus ?":"共享的照片或旅行不再到达？",
"Si un voyage partagé a été rattaché au mauvais code, ses photos et ses mises à jour ne viennent plus. L’appli retrouve le bon code de chaque voyage, sans rien effacer.":"如果共享旅行关联到了错误的代码，它的照片和更新就不再到达。应用会找回每个旅行的正确代码，不删除任何内容。",
"Profils en double":"重复的个人资料",
"Deux profils au même prénom ? Fusionne-les : tout passe sur celui que tu gardes, l’autre est supprimé chez tout le monde.":"有两个同名的个人资料？合并它们：所有内容转到保留的那个，另一个会在所有人那里删除。",
"Fusionner les profils en double":"合并重复的个人资料",
"Aucun profil en double.":"没有重复的个人资料。",
"Choisis le profil à garder : tout ce qui est au nom de l’autre passe sur lui, puis le profil en trop est supprimé, chez tout le monde.":"选择要保留的个人资料：另一个名下的所有内容都会转到它上面，然后多余的那个会在所有人那里删除。",
"Fusionner":"合并",
"{0} profil(s) en trop vont être fusionnés puis supprimés. Continuer ?":"将合并并删除 {0} 个多余的个人资料。继续吗？",
